		}

		if interactive.CanPromptInteractively() && len(resumeCtx.Sessions) > 1 {
			return runTrailResumePicker(ctx, cmd, branch, resumeCtx.Sessions, opts.Force)
		}

		return resumeTrailLatest(ctx, cmd, branch, opts.Force, "")
	})
