func trailResumeSelectorForCommands(trail trailResumeTrailContext) string {
	if trail.Number > 0 {
		return strconv.Itoa(trail.Number)
	}
	if trail.ID != "" {
		return trail.ID
	}
	return trail.Branch
}

func shellArg(s string) string {
	if s == "" {
		return "''"
	}
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == '-' || r == '_' || r == '.' || r == '/' || r == ':' {
			continue
		}
		return shellQuote(s)
	}
	return s
}

